
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pbe_jsjr_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pbe_jsjr", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.261115226301454e+00, -4.178733844427764e+00, -4.063377010688847e+00, -3.903746819400131e+00, -3.686587180621595e+00, -3.398329195724572e+00, -3.028960850263856e+00, -2.579005179941076e+00, -2.068776720884949e+00, -1.541540766290560e+00, -1.039812724308239e+00, -6.986816865668346e-01, -5.982305237724237e-01, -4.927361263918073e-01, -3.580618321011609e-01, -2.308063277890231e-01, -1.282260879752371e-01, -4.913711392843606e-02, -1.080763717439241e-02, -1.216195886067914e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


